import escapeStringRegexp from 'escape-string-regexp'
import {useEffect, useMemo, useCallback} from 'react'
import {graphql} from 'react-relay'

import {useBackgroundQuery} from '../../../../../hooks/relay/useBackgroundQuery'
import type {Properties} from '../../../../../services/rest'

import type {useQueryDependenciesParameters_allParametersQuery} from './__generated__/useQueryDependenciesParameters_allParametersQuery.graphql'
import {useQueryDependenciesSearch} from './useQueryDependenciesSearch'

import {useDebounceValue} from 'src/hooks/useDebounceValue'
import type {BuildId} from 'src/types'

const allParametersQuery = graphql`
  query useQueryDependenciesParameters_allParametersQuery($buildLocator: String!) {
    build(buildLocator: $buildLocator) {
      resultingProperties(locator: "name:(value:(^dep\\..*),matchType:matches,ignoreCase:true)") {
        property {
          name
          value
        }
      }
    }
  }
`

interface Props {
  search: string
  buildId: BuildId
  showFromDependencies: boolean
  skip: boolean
}

const SEARCH_DEBOUNCE = 500 //ms

export type DependenciesParametersState = {
  resultingProperties?: Properties | null
  startProperties: Record<string, string>
  isLoading: boolean
  isClientSearch: boolean
}

export function useQueryDependenciesParameters(props: Props) {
  const {buildId, search, showFromDependencies, skip} = props

  const [allParameters, fetchAllParameters] =
    useBackgroundQuery<useQueryDependenciesParameters_allParametersQuery>(allParametersQuery)

  const [fetchSearch, searchParameters] = useQueryDependenciesSearch()

  const debouncedSearch = useDebounceValue(search, SEARCH_DEBOUNCE)
  const normalizedSearch = useMemo(
    () => escapeStringRegexp(debouncedSearch.toLowerCase().trim()),
    [debouncedSearch],
  )
  const loadAllParameters = ['', 'd', 'de', 'dep', 'dep\\.'].includes(normalizedSearch)
  const allParametersLoaded = allParameters.data != null

  const fetch = useCallback(
    (force?: boolean) => {
      if (skip) {
        return () => undefined
      }

      if (loadAllParameters || allParametersLoaded) {
        if (showFromDependencies) {
          return fetchAllParameters(
            {
              buildLocator: `id:${buildId}`,
            },
            force,
          )
        }
        return undefined
      } else {
        return fetchSearch({
          buildId,
          normalizedSearch,
          countOnly: !showFromDependencies,
        })
      }
    },
    [
      allParametersLoaded,
      buildId,
      fetchAllParameters,
      fetchSearch,
      loadAllParameters,
      normalizedSearch,
      showFromDependencies,
      skip,
    ],
  )

  useEffect(() => {
    if (allParametersLoaded) {
      return () => undefined
    }

    return fetch()
  }, [allParametersLoaded, fetch])

  const refetch = useCallback(() => fetch(true), [fetch])

  const state: DependenciesParametersState = useMemo(() => {
    if (loadAllParameters || allParametersLoaded) {
      const {resultingProperties} = allParameters.data?.build ?? {}
      return {
        resultingProperties,
        startProperties: Object.fromEntries(
          resultingProperties?.property?.map(
            property => [property.name, property.value] as [string, string],
          ) ?? [],
        ),
        isLoading: allParameters.isLoading,
        isClientSearch: allParametersLoaded,
      }
    }

    return {...searchParameters, isClientSearch: false}
  }, [allParameters, allParametersLoaded, loadAllParameters, searchParameters])

  return {
    fetch: refetch,
    state,
  }
}
