import {useMemo} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useBuildData} from '../../../../../hooks/useEntity'
import {useThrottle} from '../../../../../hooks/useThrottle'
import type {BuildId} from '../../../../../types'
import type {Group} from '../../../../packages/Parameters/components/ParametersTree/ParametersTree'
import {ParametersTree} from '../../../../packages/Parameters/components/ParametersTree/ParametersTree'
import {inlineListMaxLength} from '../../../../packages/Parameters/Parameters.consts'
import {ParameterCategory} from '../../../../packages/Parameters/Parameters.types'
import {filterParameters} from '../../../../packages/Parameters/utils/filterParameters'
import {groupParameters} from '../../../../packages/Parameters/utils/groupParameters'
import {useBuildParametersSubscription} from '../hooks/useBuildParametersSubscription'
import {useQueryBuildParameters} from '../hooks/useQueryBuildParameters'
import type {DependenciesParametersState} from '../hooks/useQueryDependenciesParameters'

import type {BuildParametersTabParametersQuery} from './__generated__/BuildParametersTabParametersQuery.graphql'

const THROTTLER_TIMEOUT = 2000

type Props = {
  buildId: BuildId
  queryRef: PreloadedQuery<BuildParametersTabParametersQuery>
  deferredSearch: string
  modifyOnly: boolean
  dependenciesParameters: DependenciesParametersState
  showFromDependencies: boolean
  dependencies: Group
}

function BuildParametersTree(props: Props) {
  const {
    buildId,
    deferredSearch,
    modifyOnly,
    dependenciesParameters,
    showFromDependencies,
    dependencies,
  } = props

  const {fetch, state: buildParameters} = useQueryBuildParameters(props)

  const throttledFetch = useThrottle(fetch, THROTTLER_TIMEOUT)

  useBuildParametersSubscription(buildId, throttledFetch)

  const userDefinedParameters = useMemo(
    () => ({
      category: ParameterCategory.USER_DEFINED,
      original: buildParameters.originalProperties,
      groups: groupParameters(
        filterParameters({
          parameters: buildParameters.properties?.property ?? [],
          search: deferredSearch,
          modifyOnly,
          original: buildParameters.originalProperties,
        }),
      ),
    }),
    [
      buildParameters.originalProperties,
      buildParameters.properties?.property,
      modifyOnly,
      deferredSearch,
    ],
  )

  const actualOriginal = useMemo(
    () => ({
      ...buildParameters.startProperties,
      ...dependenciesParameters.startProperties,
    }),
    [buildParameters.startProperties, dependenciesParameters.startProperties],
  )

  const composite = useBuildData({buildId}, build => build?.composite)
  const parameters = useMemo(
    () => [
      userDefinedParameters,
      {
        category: composite ? ParameterCategory.ACTUAL : ParameterCategory.ACTUAL_ON_AGENT,
        original: actualOriginal,
        groups: [
          ...groupParameters(
            filterParameters({
              parameters: buildParameters.resultingProperties?.property ?? [],
              search: deferredSearch,
              modifyOnly,
              original: buildParameters.startProperties,
            }),
          ),
          ...(showFromDependencies ? [dependencies] : []),
        ],
      },
    ],
    [
      userDefinedParameters,
      actualOriginal,
      buildParameters.resultingProperties?.property,
      buildParameters.startProperties,
      deferredSearch,
      modifyOnly,
      showFromDependencies,
      dependencies,

      composite,
    ],
  )

  const totalLength =
    (buildParameters.resultingProperties?.count ?? 0) +
    (buildParameters.properties?.count ?? 0) +
    (showFromDependencies ? (dependenciesParameters.resultingProperties?.count ?? 0) : 0)

  const isVirtualized = totalLength > inlineListMaxLength

  return (
    <ParametersTree
      highlight={deferredSearch}
      parameters={parameters}
      isVirtualized={isVirtualized}
    />
  )
}

export default BuildParametersTree
