import {useCallback, useMemo} from 'react'
import {graphql, useFragment} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import {useRefetchablePreloadedQuery} from '../../../../../hooks/relay/useRefetchablePreloadedQuery'
import type {BuildParametersTabParametersQuery} from '../Parameters/__generated__/BuildParametersTabParametersQuery.graphql'
import {parametersQuery} from '../Parameters/BuildParameters.queries'

import type {useQueryBuildParametersBuild$key} from './__generated__/useQueryBuildParametersBuild.graphql'

interface Props {
  queryRef: PreloadedQuery<BuildParametersTabParametersQuery>
}

const fragment = graphql`
  fragment useQueryBuildParametersBuild on Build {
    composite
    resultingProperties(locator: "name:(value:(^dep\\..*),matchType:does-not-match)") {
      count
      property {
        name
        value
      }
    }
    startProperties(locator: "name:(value:(^dep\\..*),matchType:does-not-match)") {
      property {
        name
        value
      }
    }
    properties {
      count
      property {
        name
        value
      }
    }
    originalProperties {
      property {
        name
        value
      }
    }
  }
`

export function useQueryBuildParameters(props: Props) {
  const {queryRef} = props

  const [{build = null}, refetch] = useRefetchablePreloadedQuery(parametersQuery, queryRef)
  const fetch = useCallback(() => refetch(queryRef.variables), [queryRef, refetch])
  const data = useFragment<useQueryBuildParametersBuild$key>(fragment, build)
  const buildParametersResult = {
    properties: data?.properties,
    resultingProperties: data?.resultingProperties,
    originalProperties: data?.originalProperties ?? data?.properties,
    startProperties: data?.startProperties ?? data?.resultingProperties,
    composite: data?.composite,
  }

  const state = useMemo(() => {
    const startProperties = buildParametersResult.composite
      ? buildParametersResult.resultingProperties
      : buildParametersResult.startProperties

    return {
      properties: buildParametersResult.properties,
      resultingProperties: buildParametersResult.resultingProperties,
      originalProperties: Object.fromEntries(
        buildParametersResult.originalProperties?.property?.map(
          property => [property.name, property.value] as [string, string],
        ) ?? [],
      ),
      startProperties: Object.fromEntries(
        startProperties?.property?.map(
          property => [property.name, property.value] as [string, string],
        ) ?? [],
      ),
    }
  }, [
    buildParametersResult.composite,
    buildParametersResult.originalProperties?.property,
    buildParametersResult.properties,
    buildParametersResult.resultingProperties,
    buildParametersResult?.startProperties,
  ])

  return {
    state,
    fetch,
  }
}
