import {Suspense, useMemo} from 'react'
import type {EntryPointProps} from 'react-relay'

import {useBooleanQueryParamState, useSyncedBooleanQueryParam} from '../../../../../hooks/routes'
import useEventCallback from '../../../../../hooks/useEventCallback'
import type {BuildId} from '../../../../../types'
import {UserProperties} from '../../../../../utils/userProperties'
import Loader from '../../../../common/Loader/Loader'
import ShowDependenciesCheckbox from '../../../../packages/Parameters/components/FromDependenciesCheckbox/ShowDependenciesCheckbox'
import ParametersModifyCheckbox from '../../../../packages/Parameters/components/ModifyCheckbox/ParametersModifyCheckbox'
import ParametersPageHeader from '../../../../packages/Parameters/components/PageHeader/ParametersPageHeader'
import type {Group} from '../../../../packages/Parameters/components/ParametersTree/ParametersTree'
import ParametersSearch from '../../../../packages/Parameters/components/Search/ParametersSearch'
import {useSearchState} from '../../../../packages/Parameters/hooks/useSearchState'
import {ParameterGroup} from '../../../../packages/Parameters/Parameters.types'
import {useQueryMergedBuildParameters} from '../hooks/useQueryMergedBuildParameters'

import type {BuildParametersTabParametersQuery} from './__generated__/BuildParametersTabParametersQuery.graphql'
import BuildParametersTree from './BuildParametersTree'

import styles from './BuildParameters.module.css'

import {filterParameters} from 'src/components/packages/Parameters/utils/filterParameters'

type Queries = {parameters: BuildParametersTabParametersQuery}
export interface Props {
  buildId: BuildId
  search?: string
}

export default function BuildParameters({queries, props}: EntryPointProps<Queries, {}, Props, {}>) {
  const {buildId} = props

  const {search, deferredSearch, handleChangeSearch, handleClearSearch} = useSearchState(
    props.search,
  )

  const [showFromDependencies, setShowFromDependencies] = useSyncedBooleanQueryParam({
    param: UserProperties.BUILD_PARAMETERS_SHOW_DEPENDENCIES,
    userProperty: UserProperties.BUILD_PARAMETERS_SHOW_DEPENDENCIES,
  })

  const [modifyOnly, setModifyOnly] = useBooleanQueryParamState('onlyModified')

  const {dependenciesParameters, dependenciesTotalCount} = useQueryMergedBuildParameters({
    buildId,
    search: deferredSearch,
    showFromDependencies,
  })

  const dependencies: Group = useMemo(
    () => ({
      group: ParameterGroup.DEPENDENCIES,
      items: filterParameters({
        parameters: dependenciesParameters.resultingProperties?.property ?? [],
        search: deferredSearch,
        modifyOnly,
        original: dependenciesParameters.startProperties,
      }),
    }),
    [
      dependenciesParameters.resultingProperties?.property,
      modifyOnly,
      deferredSearch,
      dependenciesParameters.startProperties,
    ],
  )

  const handleChangeModifyOnly = useEventCallback(() => {
    setModifyOnly(!modifyOnly)
  })

  const handleChangeShowFromDependencies = useEventCallback(() => {
    setShowFromDependencies(!showFromDependencies)
  })

  const count = useMemo(() => {
    if (deferredSearch === '') {
      return undefined
    }

    if (modifyOnly) {
      return 0
    }

    if (dependenciesParameters.isClientSearch) {
      return dependencies.items.length
    }

    return dependenciesParameters?.resultingProperties?.count
  }, [
    deferredSearch,
    dependencies.items.length,
    dependenciesParameters.isClientSearch,
    dependenciesParameters?.resultingProperties?.count,
    modifyOnly,
  ])

  return (
    <>
      <ParametersPageHeader>
        <ParametersSearch
          className={styles.search}
          value={search}
          onChange={handleChangeSearch}
          onClear={handleClearSearch}
        />
        <ParametersModifyCheckbox checked={modifyOnly} onChange={handleChangeModifyOnly} />

        {dependenciesTotalCount > 0 && (
          <ShowDependenciesCheckbox
            checked={showFromDependencies}
            isLoading={dependenciesParameters.isLoading}
            count={count}
            onChange={handleChangeShowFromDependencies}
          />
        )}
      </ParametersPageHeader>

      <Suspense fallback={<Loader />}>
        <BuildParametersTree
          buildId={buildId}
          queryRef={queries.parameters}
          deferredSearch={deferredSearch}
          modifyOnly={modifyOnly}
          dependenciesParameters={dependenciesParameters}
          showFromDependencies={showFromDependencies}
          dependencies={dependencies}
        />
      </Suspense>
    </>
  )
}

export type BuildParametersComponent = typeof BuildParameters
