import {useCallback, useEffect} from 'react'
import {graphql} from 'react-relay'

import {useBackgroundQuery} from '../../../../../hooks/relay/useBackgroundQuery'
import type {BuildId} from '../../../../../types'

import type {useQueryDependenciesTotalCountQuery} from './__generated__/useQueryDependenciesTotalCountQuery.graphql'

const query = graphql`
  query useQueryDependenciesTotalCountQuery($buildLocator: String!) {
    build(buildLocator: $buildLocator) {
      resultingProperties(locator: "name:(value:(^dep\\..*),matchType:matches,ignoreCase:true)") {
        count
      }
    }
  }
`

interface Props {
  buildId: BuildId
}

export const useQueryDependenciesTotalCount = (props: Props) => {
  const [{data}, fetchQuery] = useBackgroundQuery<useQueryDependenciesTotalCountQuery>(query)
  const fetch = useCallback(
    (force?: boolean) => fetchQuery({buildLocator: `id:${props.buildId}`}, force),
    [props.buildId, fetchQuery],
  )
  useEffect(() => fetch(), [fetch])
  const refetch = useCallback(() => fetch(true), [fetch])
  return {count: data?.build?.resultingProperties?.count ?? 0, refetch}
}
