import {useCallback, useState} from 'react'
import type {GraphQLTaggedNode, OperationType, VariablesOf} from 'relay-runtime'

import {useOnDemandQuery} from './useOnDemandQuery'

type Result<T> = {
  data: T
  isLoading: boolean
}

export function useBackgroundQuery<TQuery extends OperationType>(
  gqlQuery: GraphQLTaggedNode,
): [Result<TQuery['response']>, (variables: VariablesOf<TQuery>, force?: boolean) => () => void] {
  const fetch = useOnDemandQuery(gqlQuery)
  const [data, setData] = useState<TQuery['response']>()
  const [isLoading, setIsLoading] = useState(false)

  const refetch = useCallback(
    (variables: VariablesOf<TQuery>, force?: boolean) => {
      setIsLoading(true)
      const subscription = fetch(variables, force).subscribe({
        next: response => {
          setData(response)
          setIsLoading(false)
        },
        error: () => setIsLoading(false),
      })
      return subscription.unsubscribe
    },
    [fetch],
  )
  return [{data, isLoading}, refetch]
}
