import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import {memo} from 'react'

import ParameterIcon from '../Icon/ParameterIcon'

import styles from './ParametersModifyCheckbox.module.css'

interface Props {
  checked: boolean
  onChange(): void
}

function ParametersModifyCheckbox(props: Props) {
  const {checked, onChange} = props
  return (
    <Checkbox
      containerClassName={styles.checkbox}
      labelClassName={styles.checkboxLabel}
      checked={checked}
      onChange={onChange}
    >
      {'Show only added '}
      <ParameterIcon className={styles.added} />
      {' and modified '}
      <ParameterIcon className={styles.modified} />
    </Checkbox>
  )
}

export default memo(ParametersModifyCheckbox)
