import type {Property} from '../../../../services/rest'

import {filterSearch} from './filterSearch'

interface Props {
  parameters: readonly Property[]
  search: string
  modifyOnly: boolean
  original: Record<string, string>
}

export function filterParameters(props: Props) {
  const {parameters, search, original, modifyOnly} = props

  return filterSearch({
    parameters: parameters.filter(
      parameter =>
        !modifyOnly || (parameter.name != null && parameter.value !== original[parameter.name]),
    ),
    search,
    original,
  })
}
