import {useCallback, useMemo} from 'react'
import {graphql} from 'react-relay'

import {useBackgroundQuery} from '../../../../../hooks/relay/useBackgroundQuery'

import type {useQueryDependenciesSearchQuery} from './__generated__/useQueryDependenciesSearchQuery.graphql'

import type {BuildId} from 'src/types'

const query = graphql`
  query useQueryDependenciesSearchQuery(
    $buildLocator: String!
    $propertiesLocator: String!
    $countOnly: Boolean!
  ) {
    build(buildLocator: $buildLocator) {
      resultingProperties(locator: $propertiesLocator) {
        count @include(if: $countOnly)
        property @skip(if: $countOnly) {
          name
          value
        }
      }
    }
  }
`

export function useQueryDependenciesSearch() {
  const [parametersByName, fetchParametersByName] =
    useBackgroundQuery<useQueryDependenciesSearchQuery>(query)

  const [parametersByValue, fetchParametersByValue] =
    useBackgroundQuery<useQueryDependenciesSearchQuery>(query)

  const [parametersByNameAndValue, fetchParametersByNameAndValue] =
    useBackgroundQuery<useQueryDependenciesSearchQuery>(query)

  const result = useMemo(() => {
    const propertyByName = parametersByName.data?.build?.resultingProperties?.property
    const propertyByValue = parametersByValue.data?.build?.resultingProperties?.property
    const propertyByNameAndValue =
      parametersByNameAndValue.data?.build?.resultingProperties?.property

    const property = [
      ...(propertyByName ?? []),
      ...(propertyByValue ?? []),
      ...(propertyByNameAndValue ?? []),
    ]

    const count =
      parametersByName.data?.build?.resultingProperties?.count != null &&
      parametersByValue.data?.build?.resultingProperties?.count != null &&
      parametersByNameAndValue.data?.build?.resultingProperties?.count != null
        ? parametersByName.data?.build?.resultingProperties?.count +
          parametersByValue.data?.build?.resultingProperties?.count +
          parametersByNameAndValue.data?.build?.resultingProperties?.count
        : undefined

    return {
      resultingProperties: {
        count,
        property,
      },
      startProperties: Object.fromEntries(
        property.map(value => [value.name, value.value] as [string, string]) ?? [],
      ),
      isLoading:
        parametersByName.isLoading ||
        parametersByValue.isLoading ||
        parametersByNameAndValue.isLoading,
    }
  }, [
    parametersByName.isLoading,
    parametersByName.data?.build?.resultingProperties?.count,
    parametersByName.data?.build?.resultingProperties?.property,
    parametersByNameAndValue.isLoading,
    parametersByNameAndValue.data?.build?.resultingProperties?.count,
    parametersByNameAndValue.data?.build?.resultingProperties?.property,
    parametersByValue.isLoading,
    parametersByValue.data?.build?.resultingProperties?.count,
    parametersByValue.data?.build?.resultingProperties?.property,
  ])

  const fetch = useCallback(
    (props: {buildId: BuildId; normalizedSearch: string; countOnly: boolean; force?: boolean}) => {
      const {buildId, normalizedSearch, countOnly, force} = props

      const locatorByName = `^dep\\..*${normalizedSearch}.*$`
      const unsubscribeByName = fetchParametersByName(
        {
          buildLocator: `id:${buildId}`,
          propertiesLocator: `name:(value:(${locatorByName}),matchType:matches,ignoreCase:true),value:${normalizedSearch},matchType:does-not-contain,ignoreCase:true`,
          countOnly,
        },
        force,
      )

      const locatorByValue = `^dep\\..(?!.*${normalizedSearch}).*$`
      const unsubscribeByValue = fetchParametersByValue(
        {
          buildLocator: `id:${buildId}`,
          propertiesLocator: `name:(value:(${locatorByValue}),matchType:matches,ignoreCase:true),value:${normalizedSearch},matchType:contains,ignoreCase:true`,
          countOnly,
        },
        force,
      )

      const locatorByNameAndValue = `^dep\\..*${normalizedSearch}.*$`
      const unsubscribeByNameAndValue = fetchParametersByNameAndValue(
        {
          buildLocator: `id:${buildId}`,
          propertiesLocator: `name:(value:(${locatorByNameAndValue}),matchType:matches,ignoreCase:true),value:${normalizedSearch},matchType:contains,ignoreCase:true`,
          countOnly,
        },
        force,
      )

      return () => {
        unsubscribeByName()
        unsubscribeByValue()
        unsubscribeByNameAndValue()
      }
    },
    [fetchParametersByName, fetchParametersByNameAndValue, fetchParametersByValue],
  )

  return [fetch, result] as const
}
